definition.script:
// Password Generator

var length = parseInt(input.get("length") || "16");
var mode = input.get("mode") || "strong";
var count = parseInt(input.get("count") || "1");
var includeUpper = input.get("includeUppercase") !== "false";
var includeLower = input.get("includeLowercase") !== "false";
var includeNumbers = input.get("includeNumbers") !== "false";
var includeSymbols = input.get("includeSymbols") !== "false";
var excludeAmbiguous = input.get("excludeAmbiguous") === "true";
var customSymbols = input.get("customSymbols") || "";

var uppercase = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
var lowercase = "abcdefghijklmnopqrstuvwxyz";
var numbers = "0123456789";
var symbols = "!@#$%^&*()_+-=[]{}|;:,.<>?";
var ambiguous = "0O1lI";

// Pronounceable syllables
var consonants = "bcdfghjklmnprstvwxyz";
var vowels = "aeiou";

function generateRandom(charset, len) {
    var result = "";
    for (var i = 0; i < len; i++) {
        result += charset[Math.floor(Math.random() * charset.length)];
    }
    return result;
}

function generatePronounceable(len) {
    var password = "";
    var useConsonant = Math.random() > 0.5;
    while (password.length < len) {
        if (useConsonant) {
            password += consonants[Math.floor(Math.random() * consonants.length)];
        } else {
            password += vowels[Math.floor(Math.random() * vowels.length)];
        }
        useConsonant = !useConsonant;
    }
    return password.substring(0, len);
}

function generatePassphrase(words) {
    var wordList = ["apple", "banana", "cherry", "delta", "echo", "foxtrot", "gamma", "hotel",
        "india", "juliet", "kilo", "lima", "mike", "november", "oscar", "papa", "quebec",
        "romeo", "sierra", "tango", "uniform", "victor", "whiskey", "xray", "yankee", "zulu",
        "alpha", "bravo", "charlie", "coffee", "dragon", "eagle", "falcon", "garden",
        "hammer", "island", "jungle", "kitten", "lemon", "monkey", "needle", "orange",
        "pepper", "quartz", "rabbit", "silver", "thunder", "umbrella", "violet", "wonder"];
    var phrase = [];
    for (var i = 0; i < words; i++) {
        var word = wordList[Math.floor(Math.random() * wordList.length)];
        // Capitalize first letter
        phrase.push(word.charAt(0).toUpperCase() + word.slice(1));
    }
    return phrase.join("-");
}

try {
    if (length < 4) length = 4;
    if (length > 128) length = 128;
    if (count < 1) count = 1;
    if (count > 100) count = 100;

    var passwords = [];

    for (var p = 0; p < count; p++) {
        var password = "";

        if (mode === "pronounceable") {
            password = generatePronounceable(length);
            // Optionally add some numbers at the end
            if (includeNumbers && length > 2) {
                password = password.substring(0, length - 2) + generateRandom(numbers, 2);
            }
        } else if (mode === "passphrase") {
            password = generatePassphrase(Math.max(3, Math.floor(length / 6)));
        } else if (mode === "pin") {
            password = generateRandom(numbers, length);
        } else {
            // Strong mode - build charset
            var charset = "";
            if (includeUpper) charset += uppercase;
            if (includeLower) charset += lowercase;
            if (includeNumbers) charset += numbers;
            if (includeSymbols) {
                charset += customSymbols || symbols;
            }

            if (excludeAmbiguous) {
                for (var i = 0; i < ambiguous.length; i++) {
                    charset = charset.replace(new RegExp(ambiguous[i], 'g'), '');
                }
            }

            if (charset.length === 0) charset = lowercase + numbers;

            password = generateRandom(charset, length);

            // Ensure at least one of each selected type (for strong passwords)
            if (mode === "strong" && length >= 4) {
                var pos = 0;
                if (includeUpper && password.search(/[A-Z]/) === -1) {
                    var chars = password.split('');
                    chars[pos++] = uppercase[Math.floor(Math.random() * uppercase.length)];
                    password = chars.join('');
                }
                if (includeLower && password.search(/[a-z]/) === -1) {
                    var chars = password.split('');
                    chars[pos++] = lowercase[Math.floor(Math.random() * lowercase.length)];
                    password = chars.join('');
                }
                if (includeNumbers && password.search(/[0-9]/) === -1) {
                    var chars = password.split('');
                    chars[pos++] = numbers[Math.floor(Math.random() * numbers.length)];
                    password = chars.join('');
                }
                if (includeSymbols && password.search(/[^a-zA-Z0-9]/) === -1) {
                    var chars = password.split('');
                    var syms = customSymbols || symbols;
                    chars[pos++] = syms[Math.floor(Math.random() * syms.length)];
                    password = chars.join('');
                }
            }
        }

        passwords.push(password);
    }

    // Calculate entropy
    var charsetSize = 0;
    if (mode === "pin") charsetSize = 10;
    else if (mode === "pronounceable") charsetSize = 26;
    else if (mode === "passphrase") charsetSize = 50;
    else {
        if (includeUpper) charsetSize += 26;
        if (includeLower) charsetSize += 26;
        if (includeNumbers) charsetSize += 10;
        if (includeSymbols) charsetSize += (customSymbols || symbols).length;
    }
    var entropy = Math.floor(passwords[0].length * Math.log2(Math.max(1, charsetSize)));

    output.set("Password", passwords[0]);
    output.set("Passwords", passwords.join('\n'));
    output.set("PasswordArray", json.stringify(passwords));
    output.set("Count", passwords.length);
    output.set("Length", passwords[0].length);
    output.set("Entropy", entropy);
    output.set("Strength", entropy < 28 ? "Weak" : entropy < 36 ? "Fair" : entropy < 60 ? "Good" : entropy < 128 ? "Strong" : "Very Strong");
    output.set("HasErrors", false);
    output.set("ErrorMessage", "");

    log.info("Generated " + count + " password(s), length " + length + ", entropy ~" + entropy + " bits");
    tags.trigger("success");

} catch (ex) {
    log.error("Password generation failed: " + ex.message);
    output.set("HasErrors", true);
    output.set("ErrorMessage", ex.message);
    output.set("Password", "");
    tags.trigger("error");
}
